**suggestion (performance):** The Azure upload stream buffers the entire object in memory before uploading, which can be problematic for large files.

This accumulates all chunks into memory and only uploads once in `close()`, which causes high memory usage and GC pressure for large uploads and undermines the streaming API. Since `BlockBlobClient` supports streaming (e.g., `uploadStream`) and chunked uploads, consider sending chunks directly to Azure as they arrive instead of buffering the entire payload first.

```suggestion
    async openUploadStream(input: { key: string; contentType?: string }): Promise<WritableStream> {
      const blockBlobClient = containerClient.getBlockBlobClient(input.key);

      // Stream to Azure by staging each chunk as a block and committing at close.
      // This avoids buffering the entire payload in memory.
      const blockIds: string[] = [];
      let blockIndex = 0;
      const blockIdPrefix = Date.now().toString(36) + "-" + Math.random().toString(36).slice(2, 8);

      return new WritableStream<Uint8Array | Buffer>({
        async write(chunk) {
          const buf = chunk instanceof Uint8Array ? Buffer.from(chunk) : chunk;

          const rawId = `${blockIdPrefix}-${blockIndex.toString().padStart(8, "0")}`;
          const blockId = Buffer.from(rawId).toString("base64");
          blockIndex += 1;

          // Stage the current chunk as a block immediately, so we don't accumulate
          // large amounts of data in memory.
          await blockBlobClient.stageBlock(blockId, buf, buf.length);
          blockIds.push(blockId);
        },
        async close() {
          // Commit all staged blocks as the final blob.
          await blockBlobClient.commitBlockList(blockIds, {
            blobHTTPHeaders: {
              blobContentType: input.contentType,
            },
          });
        },
        abort() {
          // No explicit cleanup: Azure will garbage-collect uncommitted blocks.
          blockIds.length = 0;
        },
      });
    },
